# Generated-site assets. No network dependencies.
CSS = r'''
:root{--bg:#f8fafc;--surface:#fff;--text:#172033;--muted:#5b6474;--line:#dbe2ea;--accent:#1d4ed8;--navy:#172554;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);line-height:1.6;padding-bottom:env(safe-area-inset-bottom)}a{color:var(--accent);text-underline-offset:.18em}.topbar{position:sticky;top:0;z-index:10;display:flex;justify-content:space-between;align-items:center;gap:16px;padding:calc(12px + env(safe-area-inset-top)) max(18px,env(safe-area-inset-right)) 12px max(18px,env(safe-area-inset-left));border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--surface) 94%,transparent);backdrop-filter:blur(14px)}.brand{font-weight:850;color:var(--navy);text-decoration:none}.topbar nav{display:flex;gap:14px;flex-wrap:wrap}.topbar nav a{color:var(--text);text-decoration:none;font-weight:700}main{width:min(1120px,calc(100% - 28px));margin:auto;padding:38px 0 64px}.hero{padding:clamp(28px,7vw,78px);border:1px solid #cbdcf8;border-radius:26px;background:linear-gradient(135deg,#eff6ff,#fff 60%,#eef2ff)}h1{font-size:clamp(2rem,6vw,4.2rem);line-height:1.08;letter-spacing:-.04em;margin:.2rem 0 1rem}.page h1,.article h1{font-size:clamp(2rem,5vw,3.2rem)}.lede{font-size:1.16rem;color:var(--muted);max-width:820px}.eyebrow{text-transform:uppercase;letter-spacing:.09em;font-size:.78rem;font-weight:800;color:var(--accent)}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.button,button,input,select{min-height:44px;font:inherit}.button{display:inline-flex;align-items:center;padding:10px 16px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--text);font-weight:750;text-decoration:none}.button.primary{background:var(--navy);color:#fff;border-color:var(--navy)}section{margin-top:44px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card,.definition,.related{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:20px}.card h2{font-size:1.08rem;margin:.35rem 0}.card p,.definition p{color:var(--muted)}.toolbar{display:grid;grid-template-columns:2fr 1fr;gap:12px;padding:14px;margin:20px 0;border:1px solid var(--line);border-radius:14px;background:var(--surface)}.toolbar label{display:grid;gap:5px;font-weight:700}.toolbar input,.toolbar select{width:100%;padding:8px 11px;border:1px solid var(--line);border-radius:9px;background:var(--surface);color:var(--text)}[hidden]{display:none!important}.article-layout{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:36px}.related{position:sticky;top:88px}.related h2{font-size:1rem}.definition{margin-bottom:12px}.status{color:var(--muted);font-size:.92rem}.privacy-box{padding:18px;border:1px solid #bfdbfe;border-radius:14px;background:#dbeafe}.link-button{border:0;background:transparent;color:var(--accent);text-decoration:underline;cursor:pointer}footer{text-align:center;color:var(--muted);padding:26px 18px calc(26px + env(safe-area-inset-bottom));border-top:1px solid var(--line)}@media(max-width:820px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.article-layout{grid-template-columns:1fr}.related{position:static}}@media(max-width:580px){main{padding-top:22px}.grid,.toolbar{grid-template-columns:1fr}.hero{padding:26px 20px;border-radius:18px}.topbar{align-items:flex-start}}@media(prefers-color-scheme:dark){:root{--bg:#0b1120;--surface:#111827;--text:#e5e7eb;--muted:#a8b0bf;--line:#2a3548;--accent:#93c5fd;--navy:#dbeafe}.hero{background:linear-gradient(135deg,#111827,#0f172a 60%,#172554);border-color:#263b65}.button.primary{background:#dbeafe;color:#172554}.privacy-box{background:#172554;border-color:#27416e}}
'''

APP = r'''
(()=>{const s=[...document.querySelectorAll("[data-status]")],set=m=>s.forEach(n=>n.textContent=m);if(!("serviceWorker"in navigator)){set("Offline mode unavailable.");return}const d=location.pathname.includes("/topics/")||location.pathname.includes("/glossary/")?"../":"./";let r;navigator.serviceWorker.register(d+"service-worker.js").then(x=>{r=x;set(navigator.onLine?"Ready.":"Offline.")}).catch(e=>set("Offline setup failed: "+e.message));async function send(type){const ready=await navigator.serviceWorker.ready;r=ready;const worker=navigator.serviceWorker.controller||ready.active;if(!worker)throw Error("service worker not active");worker.postMessage({type})}document.querySelectorAll("[data-download]").forEach(b=>b.onclick=async()=>{b.disabled=true;set("Downloading notes…");try{await send("CACHE_LIBRARY")}catch(e){set("Download failed: "+e.message);b.disabled=false}});document.querySelectorAll("[data-refresh]").forEach(b=>b.onclick=async()=>{b.disabled=true;set("Refreshing notes…");try{await send("REFRESH_LIBRARY")}catch(e){set("Refresh failed: "+e.message);b.disabled=false}});navigator.serviceWorker.addEventListener("message",e=>{const x=e.data||{};if(x.type==="CACHE_PROGRESS")set(`Offline download: ${x.completed}/${x.total}`);if(x.type==="CACHE_COMPLETE"){set("All notes are available offline.");document.querySelectorAll("button").forEach(b=>b.disabled=false)}if(x.type==="CACHE_ERROR"){set("Offline download failed: "+x.error);document.querySelectorAll("button").forEach(b=>b.disabled=false)}})})();
'''

FILTER = r'''
(()=>{const q=document.querySelector("[data-search]"),f=document.querySelector("[data-track]"),items=[...document.querySelectorAll("[data-item]")],c=document.querySelector("[data-count]");function run(){let n=0;const s=(q?.value||"").toLowerCase(),t=f?.value||"";items.forEach(x=>{const ok=(!s||x.dataset.text.includes(s))&&(!t||x.dataset.group===t);x.hidden=!ok;if(ok)n++});if(c)c.textContent=n+" result"+(n===1?"":"s")}q?.addEventListener("input",run);f?.addEventListener("change",run);run()})();
'''

SW = r'''
const V="v1",S="llm-notes-shell-"+V,L="llm-notes-library-"+V,CORE=["./","./index.html","./offline.html","./privacy.html","./manifest.webmanifest","./assets/styles.css","./assets/app.js","./assets/filter.js","./data/topics.json","./data/glossary.json","./precache-library.json","./topics/index.html","./glossary/index.html","./icons/icon.svg","./icons/icon-192.png","./icons/icon-512.png","./icons/apple-touch-icon.png"];self.addEventListener("install",e=>e.waitUntil(caches.open(S).then(c=>c.addAll(CORE))));self.addEventListener("activate",e=>e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x.startsWith("llm-notes-")&&![S,L].includes(x)).map(x=>caches.delete(x)))).then(()=>self.clients.claim())));async function note(m){for(const c of await self.clients.matchAll({includeUncontrolled:true,type:"window"}))c.postMessage(m)}async function urls(){const r=await fetch("./precache-library.json",{cache:"no-store"});if(!r.ok)throw Error("manifest "+r.status);return(await r.json()).map(x=>new URL(x,self.registration.scope).toString())}async function cacheAll(refresh){const c=await caches.open(L),u=await urls();let n=0;for(const x of u){const r=await fetch(new Request(x,{cache:refresh?"reload":"default"}));if(!r.ok)throw Error(new URL(x).pathname+" "+r.status);await c.put(x,r);await note({type:"CACHE_PROGRESS",completed:++n,total:u.length})}await note({type:"CACHE_COMPLETE"})}self.addEventListener("message",e=>{const t=e.data&&e.data.type;if(!["CACHE_LIBRARY","REFRESH_LIBRARY"].includes(t))return;e.waitUntil(cacheAll(t==="REFRESH_LIBRARY").catch(x=>note({type:"CACHE_ERROR",error:x.message})))});self.addEventListener("fetch",e=>{if(e.request.method!=="GET")return;const u=new URL(e.request.url);if(u.origin!==location.origin)return;e.respondWith(caches.match(e.request).then(x=>x||fetch(e.request).then(r=>{if(r.ok)caches.open(L).then(c=>c.put(e.request,r.clone()));return r}).catch(()=>e.request.mode==="navigate"?caches.match("./offline.html"):Response.error())))});
'''

